pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // sep is guaranteed non-empty by the problem statement.
    let sep_len = sep.len();
    let maxsplit_usize = usize::from(maxsplit);

    a.into_iter()
        .map(|s| {
            // If maxsplit == 0, do not split at all.
            if maxsplit_usize == 0 {
                return vec![s];
            }

            let mut parts_rev: Vec<String> = Vec::new();

            // Work with byte indices over the original string.
            let mut end = s.len();
            let mut splits_done = 0usize;

            while splits_done < maxsplit_usize {
                // Search for the last separator in the remaining prefix s[..end]
                let prefix = &s[..end];
                if let Some(pos) = prefix.rfind(&sep) {
                    // Right part is after the separator
                    let right_start = pos + sep_len;
                    parts_rev.push(s[right_start..end].to_string());

                    // Continue searching in the left prefix (before the separator)
                    end = pos;
                    splits_done += 1;
                } else {
                    break;
                }
            }

            // Whatever remains on the left is the final part (possibly empty).
            parts_rev.push(s[..end].to_string());

            // Reverse to restore left-to-right order.
            parts_rev.reverse();
            parts_rev
        })
        .collect()
}